def max_product_with_one_increment(n, a):
    product = 1
    for num in a:
        product *= num
    max_digit = max(a)
    if max_digit == 0:
        return 0
    if product == 0:
        return 0
    if product == 1:
        return 1
    if max_digit > product:
        return product + 1
    else:
        return product

