def min_operations_to_divisible(n, k, a):
    product = 1
    for num in a:
        product *= num
    remainder = product % k
    if remainder == 0:
        return 0
    if remainder == 1:
        return 1
    if remainder == 2:
        return 2
    if remainder == 3:
        return 3
    if remainder == 4:
        return 4
    if remainder == 5:
        return 5
    return 0

