def max_absolute_difference(n, a):
    total_weight = sum(a)
    max_weight = 0
    min_weight = 0
    for k in range(1, n + 1):
        total_weight_k = 0
        for i in range(0, n, k):
            total_weight_k += a[i]
        if total_weight_k > max_weight:
            max_weight = total_weight_k
        if total_weight_k < min_weight:
            min_weight = total_weight_k
    return max_weight - min_weight

