def max_alternating_sum(n, a):
    parity = [0] * n
    for i in range(1, n):
        if a[i] % 2 == a[i-1] % 2:
            parity[i] = 1 - parity[i-1]
        else:
            parity[i] = 1 - parity[i-1]

    max_sum = 0
    for i in range(1, n):
        if i == 1:
            max_sum = max(max_sum, a[i])
        else:
            max_sum = max(max_sum, a[i] + max_sum)

    return max_sum

