def semi_ordered_permutation(nums):
    n = len(nums)
    first_pos = 0
    last_pos = n - 1
    swaps = 0

    # Calculate the number of swaps needed to move the first element to the first position
    for i in range(1, n):
        if nums[i] != nums[first_pos]:
            swaps += 1
        first_pos += 1

    # Calculate the number of swaps needed to move the last element to the last position
    for i in range(n - 2, 0, -1):
        if nums[i] != nums[last_pos]:
            swaps += 1
        last_pos -= 1

    # Calculate the number of swaps needed to move the middle elements to their correct positions
    for i in range(1, n - 1):
        if nums[i] != nums[i - 1] and nums[i] != nums[i + 1]:
            swaps += 1
        i -= 1

    return swaps

def minCost(s: str) -> int:
    n = len(s)
    target = s[::-1]

    def invert_range(i, j):
        return sum(1 for c in s[i:j+1] if c == '0') - sum(1 for c in s[i+1:j+1] if c == '1')

    def invert_single(c):
        return 1 if c == '0' else -1

    total_cost = 0
    for i in range(n):
        if s[i] != target[i]:
            total_cost += invert_single(s[i])

    return total_cost

def is_fascinating(n: int) -> bool:
    if n < 100 or n > 999:
        return False
    n = str(n)
    n_str = str(n)
    n_str_2 = str(2 * n)
    n_str_3 = str(3 * n)
    concatenated_str = n_str + n_str_2 + n_str_3
    if len(concatenated_str) != 9:
        return False
    for digit in concatenated_str:
        if digit not in set(str(i) for i in range(1, 10)):
            return False
    return True

def count_servers_without_requests(n, logs, x, queries):
    servers_without_requests = []
    for i in range(len(queries)):
        start_time = queries[i] - x
        end_time = queries[i]
        if start_time > end_time:
            continue
        for server_id in range(1, n+1):
            if logs[server_id][0] <= start_time and logs[server_id][1] >= end_time:
                servers_without_requests.append(server_id)
    return servers_without_requests

def count_special_permutations(nums):
    MOD = 10**9 + 7
    def backtrack(start, path):
        if len(path) == len(nums):
            if all(nums[i] % nums[i+1] == 0 for i in range(len(nums)-1)):
                return 1
            return 0
        for i in range(start, len(nums)):
            if nums[i] % nums[i+1] == 0 or nums[i+1] % nums[i] == 0:
                path.append(nums[i])
                result = backtrack(i+1, path)
                if result != 0:
                    return result
                path.pop()
        return 0

    return backtrack(0, [])

def find_max_length_alternating_subarray(nums):
    max_length = -1
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] + nums[j] == nums[i] + nums[j] + 1:
                if nums[i] + nums[j] % 2 == 0:
                    max_length = max(max_length, j - i + 1)
    return max_length

def maxScore(nums, x):
    n = len(nums)
    dp = [[0] * 2 for _ in range(n)]
    dp[0][0] = nums[0]
    dp[0][1] = 0
    for i in range(1, n):
        for j in range(2):
            if nums[i] % 2 == j:
                dp[i][j] = max(dp[i-1][j], dp[i-1][j-1] + nums[i])
            else:
                dp[i][j] = max(dp[i-1][j], dp[i-1][j-1] - x)
    return dp[n-1][0]

