def count_ways(nums):
    n = len(nums)
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        for j in range(i):
            if nums[j] > i:
                dp[i] += dp[j]
    return dp[n]

def findChampion(grid):
    n = len(grid)
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                for k in range(n):
                    if k != i and k != j and grid[k][j] == 1:
                        return i
    return -1

