def insert_numbers(N, A):
    if N == 2:
        return A
    if all(abs(A[i] - A[i+1]) == 1 for i in range(N-1)):
        return A
    for i in range(N-1):
        if A[i] < A[i+1]:
            A[i+1] = A[i] + 1
        else:
            A[i+1] = A[i] - 1
    return A

