from collections import deque

def max_candy_squares(H, W, T, grid):
    start = None
    goal = None
    candy_squares = set()

    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'G':
                goal = (i, j)
            elif grid[i][j] == 'o':
                candy_squares.add((i, j))

    if start is None or goal is None:
        return -1

    queue = deque([(start, 0)])
    visited = set([start])

    while queue:
        (i, j), moves = queue.popleft()

        if (i, j) == goal:
            return moves + len(candy_squares)

        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + dx, j + dy
            if 0 <= ni < H and 0 <= nj < W and grid[ni][nj] != '#' and (ni, nj) not in visited:
                visited.add((ni, nj))
                queue.append(((ni, nj), moves + 1))

    return -1

def main():
    import sys
    input = sys.stdin.read().splitlines()
    H, W, T = map(int, input[0].split())
    grid = input[1:]

    result = max_candy_squares(H, W, T, grid)
    print(result)

