MOD = 998244353

def count_valid_strings(S):
    S = S.replace('?', 'a')
    n = len(S)
    dp = [[0] * 52 for _ in range(n + 1)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        for j in range(52):
            if S[i - 1] == j:
                dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = (dp[i - 1][j] + dp[i - 1][j - 1]) % MOD
    return dp[n][0]

def main():
    import sys
    S = sys.stdin.read().strip()
    print(count_valid_strings(S))

