def middle_occurrence(nums):
    frequencies = {}
    for num in nums:
        if num in frequencies:
            frequencies[num] += 1
        else:
            frequencies[num] = 1
    middle_occurrences = {}
    for num in nums:
        if num in frequencies:
            middle_occurrences[num] = frequencies[num] // 2
        else:
            middle_occurrences[num] = 0
    return middle_occurrences

