                dp[i][j] = (dp[i][j] + dp[i-1][j-1]) % MOD
            if j < M:
                dp[i][j] = (dp[i][j] + dp[i-1][j+1]) % MOD
    return sum(dp[N][j] for j in range(M)) % MOD

