def find_cycle(N, A):
    visited = [False] * N
    path = [None] * N
    path[0] = 0
    path[1] = 1

    def backtrack(i):
        if visited[i]:
            return False
        if i == N - 1:
            return True
        if path[i] is not None:
            return False
        visited[i] = True
        path[i] = i
        for j in range(i + 1, N):
            if A[i] == j and not visited[j]:
                if backtrack(j):
                    return True
        path[i] = None
        return False

    if backtrack(0):
        return path
    else:
        return None

