def count_holeless_squares(H, W, N, holed_squares):
    grid = [[False] * W for _ in range(H)]
    for a, b in holed_squares:
        grid[a-1][b-1] = True

    holeless_squares_count = 0

    for i in range(H):
        for j in range(W):
            for n in range(1, N+1):
                if i + n - 1 >= H or j + n - 1 >= W:
                    break
                if not grid[i][j]:
                    continue
                for k in range(n):
                    for l in range(n):
                        if i + k >= H or j + l >= W:
                            break
                        if not grid[i + k][j + l]:
                            continue
                        holeless_squares_count += 1

    return holeless_squares_count

