    # Verify distances
    for i in range(N):
        for j in range(i + 1, N):
            if distances[i][j] != distances[j][i]:
                return "undecidable"

    # Determine coordinates
    coordinates = []
    for i in range(1, N + 1):
        if i == 1:
            coordinates.append(0)
        else:
            s = distances[i - 1][i]
            t = distances[i - 1][i - 1]
            coordinates.append((s, t))

    return coordinates

