def prefix_suffix_check(N, M, S, T):
    if S == T[:N]:
        if S == T[-N:]:
            return 0
        else:
            return 1
    elif S == T[-N:]:
        if S == T[:-N]:
            return 2
        else:
            return 1
    else:
        return 3

