def find_player_numbers(N, S):
    wins = [0] * N
    for i in range(N):
        for j in range(N):
            if i != j:
                if S[i] == 'o':
                    wins[i] += 1
                elif S[j] == 'o':
                    wins[j] += 1
    sorted_wins = sorted(range(N), key=lambda x: (-wins[x], x))
    return sorted_wins

