def solve_problems(N, M, A, S):
    total_score = sum(A)
    current_score = sum(A[i] for i in range(M) if S[i] == 'o')

    for i in range(N):
        if S[i] == 'o':
            current_score += A[i]
        else:
            total_score += A[i]

        if current_score > total_score:
            return 1

    return 0

