MOD = 998244353

def mod_inverse(a, m):
    return pow(a, m - 2, m)

def calculate_probability(N, X, T):
    total_time = sum(T)
    probability = 1
    for i in range(1, N + 1):
        probability = (probability * (T[i] / total_time)) % MOD
    return mod_inverse(probability, MOD)

