def count_pairs(N, T, S):
    # Preprocess the strings to determine if they can be concatenated to form T as a subsequence
    dp = [[0] * (len(T) + 1) for _ in range(N + 1)]
    dp[0][0] = 1
    for i in range(1, N + 1):
        for j in range(1, len(T) + 1):
            for k in range(i):
                if T[j:i] in S[k:]:
                    dp[i][j] += dp[k][j-1]
    return dp[N][len(T)]

