import heapq

def min_time_to_travel(N, A, B, C, D):
    # Create a graph with cities and their distances
    graph = [[] for _ in range(N + 1)]
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            if i != j:
                graph[i].append((j, D[i-1][j-1] * A + D[j-1][i-1] * B + C))

    # Initialize the distance array with infinity
    distance = [float('inf')] * (N + 1)
    distance[1] = 0

    # Use a priority queue to find the shortest path
    pq = [(0, 1)]

    while pq:
        current_time, current_city = heapq.heappop(pq)

        if current_city == N:
            return current_time

        if current_time > distance[current_city]:
            continue

        for neighbor, time_by_car in graph[current_city]:
            time_by_train = current_time + time_by_car

            if time_by_train < distance[neighbor]:
                distance[neighbor] = time_by_train
                heapq.heappush(pq, (time_by_train, neighbor))

    return float('inf')

