def find(parent, i):
    if parent[i] != i:
        parent[i] = find(parent, parent[i])
    return parent[i]

def union(parent, rank, x, y):
    xroot = find(parent, x)
    yroot = find(parent, y)
    if xroot == yroot:
        return False
    if rank[xroot] < rank[yroot]:
        parent[xroot] = yroot
    elif rank[xroot] > rank[yroot]:
        parent[yroot] = xroot
    else:
        parent[yroot] = xroot
        rank[xroot] += 1
    return True

def minimum_spanning_tree_cost(N, M, K):
    parent = list(range(N + 1))
    rank = [0] * (N + 1)
    edges = []
    for i in range(1, M + 1):
        u, v, w = map(int, input().split())
        edges.append((u, v, w))
        u -= 1
        v -= 1
    edges.sort(key=lambda x: x[2])
    mst_cost = 0
    for u, v, w in edges:
        if union(parent, rank, u, v):
            mst_cost += w
    return mst_cost % K

