def count_valid_triples(N, S):
    # Count the number of cells with o's
    o_count = sum(1 for s in S if s == 'o')

    # Count the number of cells with x's
    x_count = sum(1 for s in S if s == 'x')

    # Count the number of cells in each row and column
    row_count = [0] * N
    col_count = [0] * N

    for i in range(N):
        for j in range(N):
            if S[i][j] == 'o':
                row_count[i] += 1
                col_count[j] += 1

    # Count the number of valid triples
    valid_triples = 0

    # Count the number of triples with exactly two cells in the same row
    for i in range(N):
        for j in range(i + 1, N):
            if row_count[i] > 0 and row_count[j] > 0:
                valid_triples += 1

    # Count the number of triples with exactly two cells in the same column
    for j in range(N):
        for i in range(j + 1, N):
            if col_count[j] > 0 and col_count[i] > 0:
                valid_triples += 1

    return valid_triples

