        queries.append((i_k, x_k))

    # Create a segment tree to store the sequence
    tree = [[] for _ in range(N+1)]
    for i in range(N):
        tree[i] = [A[i] for _ in range(N+1)]

    # Build the segment tree
    for i in range(1, N+1):
        for j in range(1, N+1):
            if i <= tree[j][0] <= j:
                tree[i].append(tree[j][0])
            else:
                tree[i].append(0)

    # Process each query
    for i_k, x_k in queries:
        tree[i_k].append(x_k)

    # Calculate the \rm{mex} of the sequence
    mex = 0
    for i in range(1, N+1):
        if not tree[i]:
            mex += 1
        else:
            mex = min(mex, tree[i][0])

    # Print the results
    for i_k, x_k in queries:
        print(mex)

