                graph[i][j] = graph[j][i]
                graph[j][i] = graph[i][j]

    distances = dijkstra(graph, X[0])

    if X[0] == X[1] == X[2] == X[3]:
        return distances[X[0]] + distances[X[1]] + distances[X[2]] + distances[X[3]]

    return distances[X[0]] + distances[X[1]] + distances[X[2]] + distances[X[3]]

