def find_minimum_walk(N, M, edges):
    def backtrack(current_vertex, visited, total_weight):
        if current_vertex == N:
            if visited == N:
                return total_weight
            else:
                return float('inf')

        min_weight = float('inf')
        for neighbor in edges[current_vertex]:
            if neighbor not in visited:
                visited.add(neighbor)
                weight = edges[current_vertex][neighbor]
                total_weight += weight
                result = backtrack(neighbor, visited, total_weight)
                if result != float('inf'):
                    min_weight = min(min_weight, result)
                visited.remove(neighbor)
        return min_weight

    return backtrack(1, set(), 0)

