import math

def prime_factors(n):
    factors = []
    while n % 2 == 0:
        factors.append(2)
        n //= 2
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        while n % i == 0:
            factors.append(i)
            n //= i
    if n > 2:
        factors.append(n)
    return factors

def generate_divisors(n, m):
    divisors = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    for i in range(1, int(math.sqrt(m)) + 1):
        if m % i == 0:
            divisors.add(i)
            divisors.add(m // i)
    return sorted(divisors)

def find_kth_smallest_divisible_by_exactly_one(n, m, k):
    divisors_n = generate_divisors(n, n)
    divisors_m = generate_divisors(m, m)
    divisors_n_and_m = set(divisors_n) | set(divisors_m)
    divisors_n_and_m_sorted = sorted(divisors_n_and_m)
    for i in range(len(divisors_n_and_m_sorted)):
        if divisors_n_and_m_sorted[i] % n == 0 and divisors_n_and_m_sorted[i] % m == 0:
            return divisors_n_and_m_sorted[i]

