def max_operations(N, M, edges, weights, pieces):
    from collections import defaultdict

    # Create adjacency list
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # Initialize weights and pieces
    weights = weights[:]
    pieces = pieces[:]

    # Perform operations
    operations = 0
    while True:
        # Try to remove one piece from a vertex
        for i in range(N):
            if pieces[i] > 0:
                for j in graph[i]:
                    if pieces[j] > 0:
                        pieces[j] -= 1
                        operations += 1
                        if pieces[j] == 0:
                            break
        if pieces[i] == 0:
            break

        # Try to place one piece on each of its adjacent vertices
        for i in range(N):
            if pieces[i] > 0:
                for j in graph[i]:
                    if pieces[j] > 0:
                        pieces[j] += 1
                        operations += 1
                        if pieces[j] == 0:
                            break
        if pieces[i] == 0:
            break

    return operations

