def parse_input():
    input = sys.stdin.read().split()
    N = int(input[0])
    M = int(input[1])
    info = []
    for i in range(M):
        l = int(input[2 + i * 3])
        d = int(input[3 + i * 3])
        k = int(input[4 + i * 3])
        c = int(input[5 + i * 3])
        A = int(input[6 + i * 3])
        B = int(input[7 + i * 3])
        info.append((l, d, k, c, A, B))
    return N, M, info

def find_latest_time(N, M, info):
    graph = defaultdict(list)
    for i in range(M):
        l, d, k, c, A, B = info[i]
        for j in range(k):
            graph[A].append((B, c))

    def dfs(node, visited):
        if node == N:
            return float('inf')
        if node in visited:
            return float('inf')
        visited.add(node)
        max_time = float('inf')
        for neighbor, c in graph[node]:
            time = dfs(neighbor, visited)
            if time > max_time:
                max_time = time
        visited.remove(node)
        return max_time

    visited = set()
    result = []
    for i in range(1, N):
        result.append(dfs(i, visited))
    return result

def main():
    N, M, info = parse_input()
    result = find_latest_time(N, M, info)
    for i in range(N):
        print(result[i] if result[i] != float('inf') else 'Unreachable')

