import sys
import bisect

def process_queries(N, A, Q, queries):
    # Create a balanced BST
    bst = [None] * (N + 1)
    for i in range(1, N + 1):
        bst[i] = bisect.bisect(A, i)

    # Process each query
    for query in queries:
        if query[0] == 1:
            x, y = query[1], query[2]
            bst[x] = y
        elif query[0] == 2:
            x = query[1]
            bst[x] = None

    # Print the final sequence
    for i in range(1, N + 1):
        print(A[i], end=" ")
    print()

