import math

def find_farthest_point(points):
    farthest_point_id = 0
    for i in range(len(points)):
        for j in range(i + 1, len(points)):
            distance = math.sqrt((points[i][0] - points[j][0])**2 + (points[i][1] - points[j][1])**2)
            if distance > farthest_point_id:
                farthest_point_id = distance
                farthest_point_id_id = points[i][0]
            elif distance == farthest_point_id:
                farthest_point_id_id = min(farthest_point_id_id, points[j][0])
    return farthest_point_id_id

