from collections import deque

def can_reach_goal(H, W, grid, medicines):
    start = None
    goal = None
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'T':
                goal = (i, j)
    if start is None or goal is None:
        return "No"

    queue = deque([(start[0], start[1], 0)])
    visited = set()
    visited.add(start)

    while queue:
        i, j, energy = queue.popleft()
        if (i, j) == goal:
            return "Yes"
        if grid[i][j] == '#':
            continue
        if grid[i][j] == 'S':
            if energy > 0:
                grid[i][j] = 'S'
                queue.append((i, j, energy - 1))
            else:
                return "No"
        if grid[i][j] == 'T':
            return "Yes"

        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < H and 0 <= nj < W and grid[ni][nj] != '#' and (ni, nj) not in visited:
                visited.add((ni, nj))
                queue.append((ni, nj, energy + 1))

    return "No"

