def find_good_sequences(L, R):
    good_sequences = []
    i = 0
    while L < R:
        j = 0
        while L < R:
            if L % (2 ** i) == 0:
                j += 1
            L //= (2 ** i)
        good_sequences.append((L, L + j))
        i += 1
    return good_sequences

def divide_sequence(good_sequences):
    M = len(good_sequences)
    l_1, r_1 = good_sequences[0]
    for i in range(1, M):
        l_2, r_2 = good_sequences[i]
        if r_2 > r_1:
            l_2, r_2 = r_2, l_2
        good_sequences[i] = (l_1, r_1) + (l_2, r_2)
    return M, good_sequences

