def transform_permutation(N, A):
    # Create a dictionary to store the positions of each element
    positions = {}
    for i in range(1, N + 1):
        positions[i] = i

    # Perform the swaps
    swap_count = 0
    for i in range(1, N + 1):
        for j in range(i + 1, N + 1):
            if i != j:
                if positions[i] != j:
                    swap_count += 1
                    positions[i], positions[j] = positions[j], positions[i]
                    break

    # Output the result
    print(swap_count)
    for i in range(1, N + 1):
        print(f"{i} {positions[i]}")

