def find_shortest_substring(arr):
    answer = []
    for i in range(len(arr)):
        for j in range(i + 1, len(arr) + 1):
            substring = ""
            for k in range(len(arr[i])):
                for l in range(k + 1, len(arr[i])):
                    substring += arr[i][k] + arr[i][l]
                    if substring not in any(substring in s for s in arr):
                        answer.append(substring)
                        break
    return answer
