def max_strength(nums, k):
    n = len(nums)
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0
    for i in range(1, n + 1):
        for j in range(1, k + 1):
            for i_start in range(i):
                for i_end in range(i_start + 1, i + 1):
                    sum_subarray = sum(nums[i_start:i_end + 1])
                    strength = sum_subarray * (j - 1) - sum_subarray * (i_end - i_start) + sum_subarray * (i_end - i_start - 1)
                    dp[i][j] = max(dp[i][j], dp[i_start][j - 1] + strength)
    return dp[n][k]

