def minMoves(nums, k, maxChanges):
    moves = 0
    for i in range(len(nums)):
        if nums[i] == 1:
            # Find the index j to move the ones to the right of i
            j = i
            while j > 0 and nums[j - 1] == 0:
                j -= 1
            if j == 0:
                # If no one is to the right of i, move the ones to the left of i
                j = i - 1
            # Perform the first type of action
            if j != i:
                nums[j] = 1
            # Perform the second type of action
            if j == i:
                nums[j] = 0
            # Update the array
            nums[j] = 0
            moves += 1
    return moves

def mostFrequentID(nums, freq):
    ans = [0] * len(nums)
    freq_dict = {}
    for i, num in enumerate(nums):
        if num in freq_dict:
            freq_dict[num] += 1
        else:
            freq_dict[num] = 1
    for i, num in enumerate(nums):
        if freq_dict[num] > ans[i]:
            ans[i] = freq_dict[num]
    return ans

def mark_and_sum(nums, queries):
    answer = []
    for index, k in queries:
        if index < 0 or index >= len(nums):
            continue
        if k == 0:
            answer.append(0)
            continue
        marked_elements = set()
        for i in range(len(nums)):
            if i not in marked_elements:
                marked_elements.add(i)
                if k > 0:
                    marked_elements.remove(i)
                if len(marked_elements) == k:
                    break
        answer.append(sum(nums[i] for i in marked_elements))
    return answer

def min_levels_to_gain_more_points(possible):
    n = len(possible)
    total_levels = n

    def calculate_points(levels):
        points = 0
        for i in range(total_levels):
            if possible[i] == 0:
                return -1
            if i < total_levels - 1:
                points += 1
            else:
                return -1
        return points

    points_alice = calculate_points(possible[:-1])
    points_bob = calculate_points(possible[1:])

    if points_alice > points_bob:
        return 1
    elif points_alice < points_bob:
        return -1
    else:
        return -1

def count_ways(k):
    dp = [0] * (k + 1)
    dp[0] = 1
    for i in range(1, k + 1):
        if i == 0:
            dp[i] = 1
        else:
            dp[i] = dp[i - 1] + dp[i - 2]
    return dp[k]

def partition_string_iterative_helper_recursive_recursive(s):
    memo = {}
    def partition_string_iterative_helper_recursive_recursive(s):
        if s in memo:
            return memo[s]
        if len(s) <= 1:
            return 1
        if s[0] != s[1]:
            memo[s] = partition_string_iterative_helper_recursive_recursive(s[1:]) + 1
        return memo[s]
    return partition_string_iterative_helper_recursive_recursive(s)
